  getr regs 1 = Z_to_bv 64 0x8e3c4 -> getr regs 2 = Z_to_bv 64 (s - 192) -> getr regs 8 = Z_to_bv 64 131072 -> getr regs 10 = Z_to_bv 64 q ->
